"use client";
/* Battery, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Battery(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("battery"); }, []);
  return React.createElement("piix-sprite", { "name": "battery", ...piixAttrs(props) });
}

export default Battery;
